function evaluateRegionHealth(regions: { id: string; latencyMs: number; errorRate: number; isAlive: boolean }[]): { healthyRegions: string[]; failoverNeeded: boolean; primaryHealthy: boolean } {
  if (regions.length === 0) return { healthyRegions: [], failoverNeeded: false, primaryHealthy: false };
  const healthy = regions.filter(r => r.isAlive && r.latencyMs < 300 && r.errorRate < 0.05).map(r => r.id);
  const primaryId = regions[0].id;
  const primaryHealthy = healthy.includes(primaryId);
  const failoverNeeded = !primaryHealthy && healthy.length > 0;
  return { healthyRegions: healthy, failoverNeeded, primaryHealthy };
}

