  if (candidates.length === 0) return null;
  candidates.sort((a, b) => b.healthScore - a.healthScore || a.capacityPercent - b.capacityPercent);
  return candidates[0].id;
}

sre-web-exam-day-9:
function resolveWeightedDns(endpoints: { ip: string; weight: number }[], randomVal: number = 0.5): string {
  if (endpoints.length === 0) return '';
  const totalWeight = endpoints.reduce((sum, e) => sum + e.weight, 0);
  if (totalWeight <= 0) return endpoints[0].ip;
  const target = randomVal * totalWeight;
  let current = 0;
  for (const ep of endpoints) {
    current += ep.weight;
    if (target <= current) return ep.ip;
  }
  return endpoints[endpoints.length - 1].ip;
}

sre-web-assign-day-9:
function resolveGeographicDns(clientLat: number, clientLon: number, regions: { id: string; lat: number; lon: number }[]): string {
  if (regions.length === 0) return '';
  let bestId = regions[0].id;
  let minDistance = Infinity;
  for (const r of regions) {
    const d = Math.sqrt(Math.pow(clientLat - r.lat, 2) + Math.pow(clientLon - r.lon, 2));
    if (d < minDistance) {
      minDistance = d;
      bestId = r.id;
    }
  }
  return bestId;
}

sre-web-exam-day-10:
function simulateMultiRegionFailover(regions: Record<string, { healthy: boolean; latencyMs: number }>, primaryRegion: string): { activeRegion: string; failoverExecuted: boolean; rtoSeconds: number } {
  if (regions[primaryRegion]?.healthy) {
    return { activeRegion: primaryRegion, failoverExecuted: false, rtoSeconds: 0 };
  }
  let bestRegion: string | null = null;
  let minLatency = Infinity;
  for (const [id, stat] of Object.entries(regions)) {
    if (id !== primaryRegion && stat.healthy && stat.latencyMs < minLatency) {
      minLatency = stat.latencyMs;
      bestRegion = id;
    }
  }
  if (!bestRegion) {
    return { activeRegion: 'none', failoverExecuted: true, rtoSeconds: -1 };
  }
  return { activeRegion: bestRegion, failoverExecuted: true, rtoSeconds: 30 };
}

