function auditRtoCompliance(incidents: { id: string; targetRtoSeconds: number; actualRecoverySeconds: number }[]): { compliantCount: number; nonCompliantCount: number; complianceRatePercent: number } {
  if (incidents.length === 0) return { compliantCount: 0, nonCompliantCount: 0, complianceRatePercent: 100 };
  const compliantCount = incidents.filter(i => i.actualRecoverySeconds <= i.targetRtoSeconds).length;
  const nonCompliantCount = incidents.length - compliantCount;
  const complianceRatePercent = Math.round((compliantCount / incidents.length) * 100 * 100) / 100;
  return { compliantCount, nonCompliantCount, complianceRatePercent };
}

