}

sre-web-assign-day-11:
function selectLeastConnections(servers: { id: string; activeConnections: number; healthy: boolean }[]): string | null {
  const healthy = servers.filter(s => s.healthy);
  if (healthy.length === 0) return null;
  let best = healthy[0];
  for (let i = 1; i < healthy.length; i++) {
    if (healthy[i].activeConnections < best.activeConnections) {
      best = healthy[i];
    }
  }
  return best.id;
}

sre-web-exam-day-12:
function evaluateProbes(status: { isProcessRunning: boolean; isDbConnected: boolean; isStartupComplete: boolean }): { canRouteTraffic: boolean; mustRestart: boolean; status: 'initializing' | 'healthy' | 'unhealthy' | 'dead' } {
  if (!status.isProcessRunning) {
    return { canRouteTraffic: false, mustRestart: true, status: 'dead' };
  }
  if (!status.isStartupComplete) {
    return { canRouteTraffic: false, mustRestart: false, status: 'initializing' };
  }
  if (!status.isDbConnected) {
    return { canRouteTraffic: false, mustRestart: false, status: 'unhealthy' };
  }
  return { canRouteTraffic: true, mustRestart: false, status: 'healthy' };
}

