sre-web-exam-day-14:
function createCircuitBreaker(failureThreshold: number = 3, resetTimeoutMs: number = 1000) {
  let state: 'CLOSED' | 'OPEN' | 'HALF_OPEN' = 'CLOSED';
  let failureCount = 0;
  let lastFailureTime = 0;
  function evaluateState(nowMs: number): 'CLOSED' | 'OPEN' | 'HALF_OPEN' {
    if (state === 'OPEN' && nowMs - lastFailureTime >= resetTimeoutMs) {
      state = 'HALF_OPEN';
    }
    return state;
  }
  return {
    recordSuccess(): void {
      state = 'CLOSED';
      failureCount = 0;
    },
    recordFailure(nowMs: number): void {
      lastFailureTime = nowMs;
      failureCount++;
      if (state === 'HALF_OPEN' || failureCount >= failureThreshold) {
        state = 'OPEN';
      }
    },
    getState(nowMs: number): 'CLOSED' | 'OPEN' | 'HALF_OPEN' {
      return evaluateState(nowMs);
    },
    canExecute(nowMs: number): boolean {
      const current = evaluateState(nowMs);
      return current !== 'OPEN';
    }
  };
}

sre-web-assign-day-14:
function formatCircuitBreakerStatus(state: 'CLOSED' | 'OPEN' | 'HALF_OPEN', failures: number, threshold: number): { status: string; isDegraded: boolean; message: string } {
  const isDegraded = state !== 'CLOSED';
  let message = '';
  if (state === 'CLOSED') message = 'Normal operation: ' + failures + '/' + threshold + ' failures';
  else if (state === 'OPEN') message = 'Circuit Tripped: rejecting downstream requests';
  else message = 'Probing downstream recovery with trial requests';
  return { status: state, isDegraded, message };
}

sre-web-exam-day-15:
function createBulkheadPool(maxConcurrent: number, maxQueue: number) {
  let active = 0;
  let queue = 0;
  return {
    tryAcquire(): boolean {
      if (active < maxConcurrent) {
        active++;
        return true;
      }
      if (queue < maxQueue) {
        queue++;
        return true;
      }
      return false;
    },
    release(): void {
      if (queue > 0) {
        queue--;
      } else if (active > 0) {
        active--;
      }
    },
    getActiveCount(): number { return active; },
    getQueueCount(): number { return queue; }
  };
}

sre-web-assign-day-15:
function calculateTimeoutBudget(clientTimeoutMs: number, hops: { service: string; maxLatencyMs: number }[]): { remainingBudgetMs: number; feasible: boolean; bottleneck: string | null } {
  if (hops.length === 0) return { remainingBudgetMs: clientTimeoutMs, feasible: true, bottleneck: null };
  const totalHopMs = hops.reduce((sum, h) => sum + h.maxLatencyMs, 0);
  const remainingBudgetMs = clientTimeoutMs - totalHopMs;
  const feasible = remainingBudgetMs >= 0;
  let bottleneck: string | null = hops[0].service;
  let maxLatency = hops[0].maxLatencyMs;
  for (let i = 1; i < hops.length; i++) {
    if (hops[i].maxLatencyMs > maxLatency) {
      maxLatency = hops[i].maxLatencyMs;
      bottleneck = hops[i].service;
    }
  }
  return { remainingBudgetMs, feasible, bottleneck };
}

