function createMetricCollector() {
  const counters: Record<string, number> = {};
  const gauges: Record<string, number> = {};
  const histograms: Record<string, { count: number; sum: number }> = {};
  return {
    incrementCounter(name: string, delta: number = 1): void {
      counters[name] = (counters[name] || 0) + delta;
    },
    setGauge(name: string, value: number): void {
      gauges[name] = value;
    },
    observeHistogram(name: string, value: number): void {
      if (!histograms[name]) histograms[name] = { count: 0, sum: 0 };
      histograms[name].count++;
      histograms[name].sum += value;
    },
    getMetrics() {
      const histOut: Record<string, { count: number; sum: number; avg: number }> = {};
      for (const [k, v] of Object.entries(histograms)) {
        const avg = v.count > 0 ? Math.round((v.sum / v.count) * 100) / 100 : 0;
        histOut[k] = { count: v.count, sum: v.sum, avg };
      }
      return { counters: { ...counters }, gauges: { ...gauges }, histograms: histOut };
    }
  };
}

