sre-web-exam-day-17:
function calculatePercentiles(observations: number[], percentiles: number[] = [50, 95, 99]): Record<number, number> {
  const out: Record<number, number> = {};
  if (observations.length === 0) {
    for (const p of percentiles) out[p] = 0;
    return out;
  }
  const sorted = [...observations].sort((a, b) => a - b);
  for (const p of percentiles) {
    const index = Math.min(sorted.length - 1, Math.max(0, Math.ceil((p / 100) * sorted.length) - 1));
    out[p] = sorted[index];
  }
  return out;
}

sre-web-assign-day-17:
function interpolateHistogramPercentile(bucketCounts: { le: number; count: number }[], totalCount: number, percentile: number): number {
  if (bucketCounts.length === 0 || totalCount <= 0) return 0;
  const target = (percentile / 100) * totalCount;
  let prevLe = 0;
  let prevCount = 0;
  for (const b of bucketCounts) {
    if (b.count >= target) {
      const countSpan = b.count - prevCount;
      if (countSpan <= 0) return b.le;
      const fraction = (target - prevCount) / countSpan;
      return Math.round((prevLe + fraction * (b.le - prevLe)) * 100) / 100;
    }
    prevLe = b.le;
    prevCount = b.count;
  }
  return bucketCounts[bucketCounts.length - 1].le;
}

