sre-web-exam-day-19:
function buildTraceTree(spans: { id: string; parentId: string | null; name: string; durationMs: number }[]): { rootId: string; totalDurationMs: number; spanCount: number; maxDepth: number } {
  if (spans.length === 0) return { rootId: '', totalDurationMs: 0, spanCount: 0, maxDepth: 0 };
  const root = spans.find(s => s.parentId === null) || spans[0];
  const childrenMap = new Map<string, string[]>();
  for (const s of spans) {
    if (s.parentId) {
      if (!childrenMap.has(s.parentId)) childrenMap.set(s.parentId, []);
      childrenMap.get(s.parentId)!.push(s.id);
    }
  }
  function getDepth(id: string): number {
    const children = childrenMap.get(id) || [];
    if (children.length === 0) return 1;
    return 1 + Math.max(...children.map(getDepth));
  }
  return {
    rootId: root.id,
    totalDurationMs: root.durationMs,
    spanCount: spans.length,
    maxDepth: getDepth(root.id)
  };
}

sre-web-assign-day-19:
function parseTraceparentHeader(header: string): { version: string; traceId: string; parentId: string; flags: string } | null {
  const parts = header.trim().split('-');
  if (parts.length !== 4) return null;
  const [version, traceId, parentId, flags] = parts;
  if (version.length !== 2 || traceId.length !== 32 || parentId.length !== 16 || flags.length !== 2) return null;
  if (version === 'ff' || !/^[0-9a-f]+$/i.test(traceId) || !/^[0-9a-f]+$/i.test(parentId)) return null;
  return { version, traceId, parentId, flags };
}

