function evaluateBurnRateAlert(windows: { windowMinutes: number; burnRate: number; threshold: number }[]): { shouldAlert: boolean; severity: 'P1' | 'P2' | 'NONE'; triggeringWindows: number[] } {
  const triggering = windows.filter(w => w.burnRate >= w.threshold);
  if (triggering.length === 0) {
    return { shouldAlert: false, severity: 'NONE', triggeringWindows: [] };
  }
  const isP1 = triggering.some(w => w.windowMinutes <= 60 && w.burnRate >= 14);
  return {
    shouldAlert: true,
    severity: isP1 ? 'P1' : 'P2',
    triggeringWindows: triggering.map(w => w.windowMinutes)
  };
}

sre-web-assign-day-20:
function deduplicateAlerts(alerts: { id: string; fingerprint: string; timestampMs: number }[], windowMs: number = 300000): { id: string; fingerprint: string; timestampMs: number }[] {
  const lastSeen = new Map<string, number>();
  const result: { id: string; fingerprint: string; timestampMs: number }[] = [];
  for (const a of alerts) {
    const last = lastSeen.get(a.fingerprint);
    if (last === undefined || a.timestampMs - last >= windowMs) {
      result.push(a);
      lastSeen.set(a.fingerprint, a.timestampMs);
    }
  }
  return result;
}

