sre-web-assign-day-21:
function calculateMttdAndMttr(incidents: { detectedAtMs: number; startedAtMs: number; resolvedAtMs: number }[]): { mttdMinutes: number; mttrMinutes: number; count: number } {
  if (incidents.length === 0) return { mttdMinutes: 0, mttrMinutes: 0, count: 0 };
  let totalD = 0;
  let totalR = 0;
  for (const i of incidents) {
    totalD += (i.detectedAtMs - i.startedAtMs) / 60000;
    totalR += (i.resolvedAtMs - i.detectedAtMs) / 60000;
  }
  const mttdMinutes = Math.round((totalD / incidents.length) * 100) / 100;
  const mttrMinutes = Math.round((totalR / incidents.length) * 100) / 100;
  return { mttdMinutes, mttrMinutes, count: incidents.length };
}

sre-web-exam-day-22:
function buildPostmortemTimeline(events: { timestampMs: number; description: string; phase: 'detection' | 'triage' | 'mitigation' | 'resolution' }[]): { durationMinutes: number; eventCount: number; orderedPhases: string[] } {
  if (events.length === 0) return { durationMinutes: 0, eventCount: 0, orderedPhases: [] };
  const sorted = [...events].sort((a, b) => a.timestampMs - b.timestampMs);
  const durationMinutes = Math.round(((sorted[sorted.length - 1].timestampMs - sorted[0].timestampMs) / 60000) * 100) / 100;
  const orderedPhases: string[] = [];
  for (const e of sorted) {
    if (!orderedPhases.includes(e.phase)) orderedPhases.push(e.phase);
  }
  return { durationMinutes, eventCount: events.length, orderedPhases };
}

sre-web-assign-day-22:
function validateActionItems(items: { description: string; owner: string; dueDateIso: string; priority: 'P0' | 'P1' | 'P2' }[]): { valid: boolean; missingFields: string[] } {
  const missing: string[] = [];
  const validPriorities = new Set(['P0', 'P1', 'P2']);
  for (let i = 0; i < items.length; i++) {
    const it = items[i];
    if (!it.description || !it.description.trim()) missing.push('item[' + i + '].description');
    if (!it.owner || !it.owner.trim()) missing.push('item[' + i + '].owner');
    if (!it.dueDateIso || !it.dueDateIso.trim()) missing.push('item[' + i + '].dueDateIso');
    if (!validPriorities.has(it.priority)) missing.push('item[' + i + '].priority');
  }
  return { valid: missing.length === 0, missingFields: missing };
}

sre-web-exam-day-23:
function applyLittlesLaw(arrivalRatePerSec: number, avgLatencySec: number): { avgConcurrency: number; recommendedCapacity: number } {
  const avgConcurrency = Math.round(arrivalRatePerSec * avgLatencySec * 100) / 100;
  const recommendedCapacity = Math.ceil(avgConcurrency * 1.5);
  return { avgConcurrency, recommendedCapacity };
}

sre-web-assign-day-23:
function calculateAutoScalingDesired(currentReplicas: number, currentMetric: number, targetMetric: number, minReplicas: number = 2, maxReplicas: number = 20): number {
  if (targetMetric <= 0) return maxReplicas;
  const desired = Math.ceil(currentReplicas * (currentMetric / targetMetric));
  return Math.min(maxReplicas, Math.max(minReplicas, desired));
}

sre-web-exam-day-24:
function modelCloudComputeCost(hourlyUsageHours: number, onDemandRate: number, reservedRate: number, upfrontCost: number = 0): { onDemandCost: number; reservedCost: number; savings: number; breakEvenReached: boolean } {
  const onDemandCost = Math.round(hourlyUsageHours * onDemandRate * 100) / 100;
  const reservedCost = Math.round((upfrontCost + hourlyUsageHours * reservedRate) * 100) / 100;
  const savings = Math.round((onDemandCost - reservedCost) * 100) / 100;
  return { onDemandCost, reservedCost, savings, breakEvenReached: savings > 0 };
}

sre-web-assign-day-24:
function evaluateSpotReliabilityRisk(spotInterruptionRatePercent: number, basePrice: number, spotPrice: number, maxToleratedInterruptionPercent: number = 10): { useSpot: boolean; costSavingsPercent: number; reason: string } {
  const costSavingsPercent = Math.round(((basePrice - spotPrice) / basePrice) * 100 * 100) / 100;
  if (spotInterruptionRatePercent > maxToleratedInterruptionPercent) {
    return { useSpot: false, costSavingsPercent, reason: 'Interruption risk exceeds tolerance' };
  }
  return { useSpot: true, costSavingsPercent, reason: 'Cost efficient and within risk parameters' };
}

sre-web-exam-day-25:
function evaluateIncidentLifecycle(incident: { id: string; startedAtMs: number; detectedAtMs: number; mitigatedAtMs: number; resolvedAtMs: number; errorRatePeak: number }): { ttdMinutes: number; ttmMinutes: number; ttrMinutes: number; severity: 'SEV1' | 'SEV2' | 'SEV3'; postmortemRequired: boolean } {
  const ttdMinutes = Math.round(((incident.detectedAtMs - incident.startedAtMs) / 60000) * 100) / 100;
  const ttmMinutes = Math.round(((incident.mitigatedAtMs - incident.detectedAtMs) / 60000) * 100) / 100;
  const ttrMinutes = Math.round(((incident.resolvedAtMs - incident.startedAtMs) / 60000) * 100) / 100;
  const severity: 'SEV1' | 'SEV2' | 'SEV3' = incident.errorRatePeak >= 0.2 ? 'SEV1' : incident.errorRatePeak >= 0.05 ? 'SEV2' : 'SEV3';
  const postmortemRequired = severity === 'SEV1' || severity === 'SEV2';
  return { ttdMinutes, ttmMinutes, ttrMinutes, severity, postmortemRequired };
}

sre-web-assign-day-25:
function aggregateObservabilitySignals(metricsHealthy: boolean, logErrorSpike: boolean, traceLatencyHigh: boolean): { systemHealth: 'healthy' | 'degraded' | 'critical'; anomalies: string[] } {
  const anomalies: string[] = [];
  if (!metricsHealthy) anomalies.push('METRICS_DEGRADED');
  if (logErrorSpike) anomalies.push('LOG_ERROR_SPIKE');
  if (traceLatencyHigh) anomalies.push('TRACE_HIGH_LATENCY');
  if (anomalies.length >= 2 || (!metricsHealthy && logErrorSpike)) {
    return { systemHealth: 'critical', anomalies };
  }
  if (anomalies.length === 1) {
    return { systemHealth: 'degraded', anomalies };
  }
  return { systemHealth: 'healthy', anomalies };
}

sre-web-exam-day-26:
function evaluateChaosExperiment(steadyState: { maxLatencyMs: number; maxErrorRate: number }, baseline: { latencyMs: number; errorRate: number }, underChaos: { latencyMs: number; errorRate: number }): { hypothesisPassed: boolean; latencyDegradationPercent: number; errorRateDelta: number } {
  const hypothesisPassed = underChaos.latencyMs <= steadyState.maxLatencyMs && underChaos.errorRate <= steadyState.maxErrorRate;
  const latencyDegradationPercent = Math.round(((underChaos.latencyMs - baseline.latencyMs) / baseline.latencyMs) * 100 * 100) / 100;
  const errorRateDelta = Math.round((underChaos.errorRate - baseline.errorRate) * 10000) / 10000;
  return { hypothesisPassed, latencyDegradationPercent, errorRateDelta };
}

sre-web-assign-day-26:
function calculateBlastRadius(targetService: string, downstreamServices: Record<string, string[]>): { affectedCount: number; affectedServices: string[] } {
  const visited = new Set<string>();
  const queue = [...(downstreamServices[targetService] || [])];
  while (queue.length > 0) {
    const curr = queue.shift()!;
    if (!visited.has(curr)) {
      visited.add(curr);
      for (const next of (downstreamServices[curr] || [])) {
        if (!visited.has(next)) queue.push(next);
      }
    }
  }
  const affectedServices = Array.from(visited).sort();
  return { affectedCount: affectedServices.length, affectedServices };
}

sre-web-exam-day-27:
function simulateBlueGreenSwitch(activeColor: 'blue' | 'green', greenHealth: boolean, blueHealth: boolean): { nextColor: 'blue' | 'green'; switched: boolean; rollbackNeeded: boolean } {
  if (activeColor === 'blue') {
    if (greenHealth) return { nextColor: 'green', switched: true, rollbackNeeded: false };
    return { nextColor: 'blue', switched: false, rollbackNeeded: true };
  } else {
    if (blueHealth) return { nextColor: 'blue', switched: true, rollbackNeeded: false };
    return { nextColor: 'green', switched: false, rollbackNeeded: true };
  }
}

sre-web-assign-day-27:
function planRollingUpdateSteps(totalInstances: number, maxUnavailable: number = 1, maxSurge: number = 1): { totalSteps: number; batchSize: number; maxSurgeCapacity: number } {
  const batchSize = Math.max(1, maxUnavailable);
  const maxSurgeCapacity = totalInstances + maxSurge;
  const totalSteps = Math.ceil(totalInstances / batchSize);
  return { totalSteps, batchSize, maxSurgeCapacity };
}

sre-web-exam-day-28:
function evaluateCanaryPromotion(baseline: { errorRate: number; p99LatencyMs: number }, canary: { errorRate: number; p99LatencyMs: number }, thresholds: { maxErrorRateIncrease: number; maxLatencyIncreasePercent: number }): { promote: boolean; reason: string } {
  const errorIncrease = canary.errorRate - baseline.errorRate;
  const latencyIncreasePercent = ((canary.p99LatencyMs - baseline.p99LatencyMs) / baseline.p99LatencyMs) * 100;
  if (errorIncrease > thresholds.maxErrorRateIncrease) {
    return { promote: false, reason: 'Error rate threshold exceeded' };
  }
  if (latencyIncreasePercent > thresholds.maxLatencyIncreasePercent) {
    return { promote: false, reason: 'Latency regression threshold exceeded' };
  }
  return { promote: true, reason: 'Canary healthy and within thresholds' };
}

sre-web-assign-day-28:
function calculateCanaryTrafficSteps(currentTrafficPercent: number, targetTrafficPercent: number = 100, stepPercent: number = 10): number[] {
  const steps: number[] = [];
  let curr = currentTrafficPercent + stepPercent;
  while (curr < targetTrafficPercent) {
    steps.push(curr);
    curr += stepPercent;
  }
  if (currentTrafficPercent < targetTrafficPercent) {
    steps.push(targetTrafficPercent);
  }
  return steps;
}

sre-web-exam-day-29:
function executeRunbookDecisionTree(node: { condition: string; action?: string; yesBranch?: any; noBranch?: any }, state: Record<string, boolean>): { executedActions: string[]; finalState: 'resolved' | 'escalate' } {
  const actions: string[] = [];
  let curr: any = node;
  while (curr) {
    if (curr.action) actions.push(curr.action);
    if (!curr.condition) break;
    const condVal = Boolean(state[curr.condition]);
    curr = condVal ? curr.yesBranch : curr.noBranch;
  }
  const lastAction = actions[actions.length - 1] || '';
  const finalState = lastAction.toLowerCase().includes('escalat') ? 'escalate' : 'resolved';
  return { executedActions: actions, finalState };
}

sre-web-assign-day-29:
function auditRunbookCoverage(incidentTypes: string[], runbooks: { incidentType: string; automatedActionCount: number }[]): { coveragePercent: number; unmappedTypes: string[]; fullyAutomatedCount: number } {
  if (incidentTypes.length === 0) return { coveragePercent: 100, unmappedTypes: [], fullyAutomatedCount: 0 };
  const mappedSet = new Set(runbooks.map(r => r.incidentType));
  const unmappedTypes = incidentTypes.filter(t => !mappedSet.has(t));
  const mappedCount = incidentTypes.length - unmappedTypes.length;
  const coveragePercent = Math.round((mappedCount / incidentTypes.length) * 100 * 100) / 100;
  const fullyAutomatedCount = runbooks.filter(r => r.automatedActionCount >= 3).length;
  return { coveragePercent, unmappedTypes, fullyAutomatedCount };
}

sre-web-exam-day-30:
function generateReliabilityScorecard(services: { id: string; sliAvailability: number; sloTarget: number; chaosPassed: boolean; canarySafe: boolean }[]): { overallScore: number; grade: 'A' | 'B' | 'C' | 'D' | 'F'; passingServices: number; totalServices: number } {
  if (services.length === 0) return { overallScore: 100, grade: 'A', passingServices: 0, totalServices: 0 };
  let totalScore = 0;
  let passingCount = 0;
  for (const s of services) {
    const sliScore = s.sliAvailability >= s.sloTarget ? 40 : Math.max(0, 40 - (s.sloTarget - s.sliAvailability) * 10);
    const chaosScore = s.chaosPassed ? 30 : 0;
    const canaryScore = s.canarySafe ? 30 : 0;
    const serviceScore = sliScore + chaosScore + canaryScore;
    if (serviceScore >= 80) passingCount++;
    totalScore += serviceScore;
  }
  const overallScore = Math.round((totalScore / services.length) * 100) / 100;
  let grade: 'A' | 'B' | 'C' | 'D' | 'F' = 'F';
  if (overallScore >= 90) grade = 'A';
  else if (overallScore >= 80) grade = 'B';
  else if (overallScore >= 70) grade = 'C';
  else if (overallScore >= 60) grade = 'D';
  return { overallScore, grade, passingServices: passingCount, totalServices: services.length };
}

